    css: "body { margin: 0; }\n    a { color: #5b88f7; } a:hover { color: #8fb0fa; }\n    .cl { font-family: \"SF Mono\", ui-monospace, Menlo, monospace; }\n    .row { display: flex; align-items: center; justify-content: space-between; gap: 14px; min-height: 52px; padding: 13px 0; border-bottom: 1px solid rgba(242,244,238,0.08); }\n    .card { padding: 20px 22px; background: rgba(242,244,238,0.025); border: 1px solid rgba(242,244,238,0.11); border-radius: 6px; }\n    .sw { position: relative; width: 34px; height: 20px; border-radius: 10px; background: #3d454e; flex-shrink: 0; }\n    .sw i { position: absolute; top: 3px; left: 3px; width: 14px; height: 14px; border-radius: 50%; background: #c9cec8; }\n    .sw.on { background: #6b7280; }\n    .sw.on i { left: 17px; background: #f1f3ef; }\n    .mica-thin { background: #343a45; }",
    html: "<div style=\"width: 1440px; height: 900px; display: flex; flex-direction: column; overflow: hidden; background: #282c34; color: #f1f3ef; font-family: -apple-system, BlinkMacSystemFont, 'Hiragino Sans', 'Hiragino Kaku Gothic ProN', 'SF Pro Text', system-ui, sans-serif; font-size: 11px; -webkit-font-smoothing: antialiased;\">\n\n  <div class=\"mica-thin\" style=\"height: 48px; flex-shrink: 0; display: flex; align-items: center; gap: 12px; padding: 0 16px; background-color: #282c34; border-bottom: 1px solid rgba(242,244,238,0.1);\">\n    <div style=\"display: flex; align-items: center; gap: 8px;\">\n      <div style=\"width: 12px; height: 12px; border-radius: 50%; background: #ff5f57;\"></div>\n      <div style=\"width: 12px; height: 12px; border-radius: 50%; background: #febc2e;\"></div>\n      <div style=\"width: 12px; height: 12px; border-radius: 50%; background: #28c840;\"></div>\n    </div>\n    <div style=\"width: 1px; height: 22px; background: rgba(242,244,238,0.11); margin: 0 4px;\"></div>\n    <span style=\"font-size: 13px; font-weight: 600;\">\u8a2d\u5b9a</span>\n    <div style=\"flex: 1;\"></div>\n    <div style=\"display: flex; align-items: center; justify-content: center; width: 26px; height: 26px; border-radius: 6px; color: #9ba19b;\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M3.5 3.5l9 9M12.5 3.5l-9 9\"/></svg></div>\n  </div>\n\n  <div style=\"flex: 1; display: grid; grid-template-columns: 232px minmax(0,1fr); min-height: 0;\">\n    <div class=\"mica-thin\" style=\"min-width: 0; display: flex; flex-direction: column; gap: 14px; overflow: hidden; padding: 18px 10px; border-right: 1px solid rgba(242,244,238,0.1);\">\n      <div style=\"display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 8px; border-radius: 5px; background: #282c34; border: 1px solid rgba(242,244,238,0.19); color: #55605a; font-size: 11px;\">\u8a2d\u5b9a\u3092\u691c\u7d22</div>\n      <nav>\n        <div style=\"margin: 6px 8px 6px; color: #55605a; font-size: 9px; font-weight: 700; letter-spacing: 0.06em;\">\u30ef\u30fc\u30af\u30b9\u30da\u30fc\u30b9</div>\n        <div style=\"min-height: 30px; display: flex; align-items: center; gap: 8px; padding: 0 8px; border-radius: 4px; background: rgba(242,244,238,0.075); color: #f1f3ef; font-size: 11px; font-weight: 600;\">\u4e00\u822c</div>\n        <div style=\"min-height: 30px; display: flex; align-items: center; gap: 8px; padding: 0 8px; border-radius: 4px; color: #9ba19b; font-size: 11px;\">AI\u30d7\u30ed\u30d0\u30a4\u30c0\u30fc</div>\n        <div style=\"min-height: 30px; display: flex; align-items: center; gap: 8px; padding: 0 8px; border-radius: 4px; color: #9ba19b; font-size: 11px;\">\u30a8\u30c7\u30a3\u30bf</div>\n        <div style=\"min-height: 30px; display: flex; align-items: center; gap: 8px; padding: 0 8px; border-radius: 4px; color: #9ba19b; font-size: 11px;\">\u30bf\u30fc\u30df\u30ca\u30eb</div>\n        <div style=\"min-height: 30px; display: flex; align-items: center; gap: 8px; padding: 0 8px; border-radius: 4px; color: #9ba19b; font-size: 11px;\">\u30e2\u30d0\u30a4\u30eb</div>\n        <div style=\"min-height: 30px; display: flex; align-items: center; gap: 8px; padding: 0 8px; border-radius: 4px; color: #9ba19b; font-size: 11px;\">\u30a2\u30c3\u30d7\u30c7\u30fc\u30c8</div>\n      </nav>\n    </div>\n\n    <div style=\"min-width: 0; overflow: hidden; padding: 40px 56px; background: #1e2127;\">\n      <div style=\"max-width: 720px; margin: 0 auto;\">\n        <h1 style=\"margin: 0; font-size: 20px; font-weight: 600; letter-spacing: -0.01em;\">\u4e00\u822c</h1>\n        <p style=\"margin: 8px 0 24px; color: #9ba19b; font-size: 12px; line-height: 1.6;\">\u30ef\u30fc\u30af\u30b9\u30da\u30fc\u30b9\u306e\u57fa\u672c\u52d5\u4f5c\u3068\u30a2\u30d7\u30ea\u5168\u4f53\u306e\u8868\u793a\u3092\u8a2d\u5b9a\u3057\u307e\u3059\u3002</p>\n\n        <div class=\"card\" style=\"margin-bottom: 14px;\">\n          <div style=\"margin-bottom: 16px;\"><h2 style=\"margin: 0; font-size: 13px; font-weight: 600;\">\u30ef\u30fc\u30af\u30b9\u30da\u30fc\u30b9</h2><p style=\"margin: 4px 0 0; color: #9ba19b; font-size: 11px; line-height: 1.5;\">Project\u3092\u958b\u304f\u3068\u304d\u306b\u4f7f\u3046\u57fa\u672c\u8a2d\u5b9a\u3067\u3059\u3002</p></div>\n          <div class=\"row\" style=\"border-top: 1px solid rgba(242,244,238,0.08);\">\n            <div><strong style=\"display: block; font-size: 12px; font-weight: 500; color: #f1f3ef;\">\u30ef\u30fc\u30af\u30b9\u30da\u30fc\u30b9\u306e\u30c7\u30a3\u30ec\u30af\u30c8\u30ea</strong><small style=\"display: block; margin-top: 3px; color: #9ba19b; font-size: 10.5px;\">Project\u3092\u307e\u3068\u3081\u3066\u7ba1\u7406\u3059\u308b\u30d5\u30a9\u30eb\u30c0\u3067\u3059\u3002</small></div>\n            <div class=\"cl\" style=\"min-height: 30px; padding: 0 10px; display: flex; align-items: center; border: 1px solid rgba(242,244,238,0.19); border-radius: 4px; background: #101214; color: #c9cec8; font-size: 11px;\">~/Projects</div>\n          </div>\n          <div class=\"row\"><div><strong style=\"display: block; font-size: 12px; font-weight: 500; color: #f1f3ef;\">\u524d\u56de\u306e\u30ec\u30a4\u30a2\u30a6\u30c8\u3092\u5fa9\u5143</strong><small style=\"display: block; margin-top: 3px; color: #9ba19b; font-size: 10.5px;\">Project\u3054\u3068\u306e\u30d5\u30a1\u30a4\u30eb\u3001\u30bf\u30fc\u30df\u30ca\u30eb\u3001\u5206\u5272\u4f4d\u7f6e\u3092\u518d\u958b\u3057\u307e\u3059\u3002</small></div><div class=\"sw on\"><i></i></div></div>\n          <div class=\"row\" style=\"border-bottom: 0;\"><div><strong style=\"display: block; font-size: 12px; font-weight: 500; color: #f1f3ef;\">\u9589\u3058\u308b\u524d\u306b\u78ba\u8a8d</strong><small style=\"display: block; margin-top: 3px; color: #9ba19b; font-size: 10.5px;\">\u5b9f\u884c\u4e2d\u306e\u30bf\u30fc\u30df\u30ca\u30eb\u3084\u672a\u4fdd\u5b58\u306e\u30a8\u30c7\u30a3\u30bf\u3092\u9589\u3058\u308b\u524d\u306b\u78ba\u8a8d\u3057\u307e\u3059\u3002</small></div><div class=\"sw on\"><i></i></div></div>\n        </div>\n\n        <div class=\"card\">\n          <div style=\"margin-bottom: 16px;\"><h2 style=\"margin: 0; font-size: 13px; font-weight: 600;\">\u30a4\u30f3\u30bf\u30fc\u30d5\u30a7\u30fc\u30b9</h2><p style=\"margin: 4px 0 0; color: #9ba19b; font-size: 11px; line-height: 1.5;\">\u30ef\u30fc\u30af\u30b9\u30da\u30fc\u30b9\u3092\u9759\u304b\u3067\u96c6\u4e2d\u3057\u3084\u3059\u3044\u8868\u793a\u306b\u3057\u307e\u3059\u3002</p></div>\n          <div class=\"row\" style=\"border-top: 1px solid rgba(242,244,238,0.08); border-bottom: 0;\"><div><strong style=\"display: block; font-size: 12px; font-weight: 500; color: #f1f3ef;\">\u30b9\u30c6\u30fc\u30bf\u30b9\u30d0\u30fc\u306e\u5229\u7528\u67a0\u3092\u8868\u793a</strong><small style=\"display: block; margin-top: 3px; color: #9ba19b; font-size: 10.5px;\">\u6700\u3082\u903c\u8feb\u3057\u305fAgent\u306e\u5229\u7528\u67a0\u3092\u3001\u3059\u3079\u3066\u306e\u753b\u9762\u306estatus bar\u306b\u8868\u793a\u3057\u307e\u3059\u3002</small></div><div class=\"sw on\"><i></i></div></div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>",
